import pandas as pd
import numpy as np

# Load data
data = pd.read_csv('chunks_csv/getisord/getisord_2023_crime.csv')
data['Crime_value'] = data['Crime_value'].fillna(data['Crime_value'].median())

# Load adjacency data
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Create a dictionary where each key is a borough name and the value is a list of its neighboring boroughs
neighbor_dict = {}
for i, row in adjacency.iterrows():
    if row['borough'] not in neighbor_dict:
        neighbor_dict[row['borough']] = []
    neighbor_dict[row['borough']].append(row['neighbor'])

# Calculate combined totals
combined_totals = {}
for index, row in data.iterrows():
    if row['Crime_value'] not in combined_totals:
        combined_totals[row['Crime_value']] = 0
    for neighbor in neighbor_dict.get(row['borough'], []):
        if neighbor in data['borough'].values:
            combined_totals[row['Crime_value']] += data.loc[data['borough'] == neighbor, 'Crime_value'].values[0]

# Calculate citywide average
citywide_average = combined_totals.values().sum() / len(combined_totals)

# Apply Getis-Ord Gi* method
z_scores = {}
for crime_value, total in combined_totals.items():
    z = (total - citywide_average) / np.sqrt((len(data) - 1) * (data['Crime_value'].mean() ** 2))
    z_scores[crime_value] = z

# Handle missing values
data_points_used = len(data) - data['Crime_value'].isnull().sum()

# Identify hot and cold spots
hot_spots = {k: v for k, v in z_scores.items() if abs(v) > 1.96}
cold_spots = {k: v for k, v in z_scores.items() if abs(v) > 1.96 and k not in hot_spots}

# Print results
print(f"data_points_used = {data_points_used}")
if hot_spots or cold_spots:
    print(f"FINAL ANSWER: {', '.join(f'{borough} (HOT, Gi*={value})' for borough, value in hot_spots.items())}, {', '.join(f'{borough} (COLD, Gi*={value})' for borough, value in cold_spots.items())}")
else:
    print("FINAL ANSWER: none")

import pandas as pd
import numpy as np

# Load data
data = pd.read_csv('chunks_csv/getisord/getisord_2023_crime.csv')
data['Crime_value'] = data['Crime_value'].fillna(data['Crime_value'].median())

# Load adjacency data
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Create a dictionary where each key is a borough name and the value is a list of its neighboring boroughs
neighbors = {}
for index, row in adjacency_data.iterrows():
    if row['borough'] not in neighbors:
        neighbors[row['borough']] = []
    neighbors[row['borough']].append(row['neighbor'])

# Calculate combined totals
combined_totals = {}
for index, row in data.iterrows():
    if row['borough'] not in combined_totals:
        combined_totals[row['borough']] = 0
    if row['borough'] in neighbors:
        for neighbor in neighbors[row['borough']]:
            if neighbor in combined_totals:
                combined_totals[row['borough']] += data.loc[data['borough'] == neighbor, 'Crime_value'].values[0]
                combined_totals[neighbor] += data.loc[data['borough'] == row['borough'], 'Crime_value'].values[0]
    else:
        combined_totals[row['borough']] += row['Crime_value']

# Calculate citywide average
citywide_average = np.mean(list(combined_totals.values()))

# Apply Getis-Ord Gi* method
z_scores = {}
for index, row in data.iterrows():
    if row['Crime_value'] != 0:
        if row['borough'] in combined_totals:
            z_score = (combined_totals[row['borough']] - citywide_average) / (citywide_average * (1 + (1 / len(data))))
            z_scores[row['borough']] = z_score

# Identify hot and cold spots
hot_spots = []
cold_spots = []
for borough, z_score in z_scores.items():
    if np.abs(z_score) > 1.96:
        if z_score > 0:
            hot_spots.append((borough, z_score))
        else:
            cold_spots.append((borough, z_score))

# Print results
print(f"data_points_used = {len(data) - data['Crime_value'].isnull().sum()}")
if len(hot_spots) + len(cold_spots) > 0:
    print(f"FINAL ANSWER: {', '.join([f'{borough} (HOT, Gi*={z_score:.4f})' for borough, z_score in hot_spots] + [f'{borough} (COLD, Gi*={z_score:.4f})' for borough, z_score in cold_spots])}")
else:
    print("FINAL ANSWER: none")
